-- tests/behaviour/resource_depth.sql on both engines.

--! server
SET ROLE identity_writer;

-- The founding grant stamps the organization on the server.
--! client user=10000000-0000-7000-8000-000000000001 expect=ok diverges=organizations

-- Twenty-one resource levels are rejected.
--! client user=10000000-0000-7000-8000-000000000001 upload=23514

-- Twenty resource levels exclude the organization when inheriting its archive.
-- Only the server carries the archive into the copies of the rows below it.
--! client user=10000000-0000-7000-8000-000000000001 expect=ok diverges=resources,resource_parents,ownables,grants
UPDATE resources SET archived_at = '2126-01-01 00:00:00.000000+00:00' WHERE id = X'20000000000070008000000000000001';
